from rdflib import Graph

g = Graph()
g.parse("/app/university_graph.ttl", format="turtle")

# Debug: check Marie Dubois specifically
query = """
PREFIX uni: <http://university.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?professorName ?dept2 ?course ?studentName
WHERE {
    uni:Marie_Dubois a uni:Person ;
             uni:hasName ?professorName ;
             uni:role ?role .
    FILTER(CONTAINS(?role, "Professor") && !CONTAINS(?role, "Assistant"))

    uni:Marie_Dubois uni:worksIn ?dept2 .
    ?course a uni:Course ;
            uni:isTaughtIn ?dept2 .
    ?student a uni:Person ;
             uni:role "Student" ;
             uni:hasName ?studentName ;
             uni:isEnrolledIn ?course ;
             uni:hasEnrollmentDate ?enrollDate .
    OPTIONAL { ?student uni:hasGraduationDate ?gradDate } .
    FILTER(!BOUND(?gradDate) || ?gradDate > "2025-08-16"^^xsd:date)
}
"""
results = list(g.query(query))
print(f"Marie Dubois matches: {len(results)}")
for r in results:
    print(f"  Dept: {r.dept2}, Course: {r.course}, Student: {r.studentName}")
